<?php
declare(strict_types=1);
/** Fixed-host adapter. Only reviewed public entrances may reach the provider. */
function journeyWalking(string $from,string $to,bool $stepFree=false): array {
 $file=STORAGE_PATH.'/walking-provider.json';$config=is_file($file)?json_decode(file_get_contents($file),true):[];
 if(empty($config['enabled'])||empty($config['api_key'])||($config['provider']??'')!=='openrouteservice')return ['status'=>'NEEDS_DATA','reason'=>'WALKING_PROVIDER_UNCONFIGURED'];
 $points=[];$versions=[];foreach([$from,$to] as $id){$f=journeyFact($id,'entrance');if(!JourneyEngine::current($f,time(),date('Y-m-d'),'entrance'))return ['status'=>'NEEDS_DATA','reason'=>'ENTRANCE_UNKNOWN'];$v=$f['value'];if(!is_numeric($v['longitude']??null)||!is_numeric($v['latitude']??null)||abs($v['longitude'])>180||abs($v['latitude'])>90)return ['status'=>'NEEDS_DATA','reason'=>'ENTRANCE_UNKNOWN'];$points[]=[(float)$v['longitude'],(float)$v['latitude']];$versions[]=$f['version'];}
 $cacheKey=hash('sha256',json_encode(['foot-walking',$points,$versions,$stepFree]));$dir=STORAGE_PATH.'/walking-cache';if(!is_dir($dir))mkdir($dir,0700,true);$cached=$dir.'/'.$cacheKey.'.json';
 $ttl=max(0,min(86400,(int)($config['cache_ttl_seconds']??0)));if($ttl&&is_file($cached)&&filemtime($cached)>time()-$ttl)return json_decode(file_get_contents($cached),true);
 $lock=fopen($dir.'/quota.lock','c+');if(!$lock||!flock($lock,LOCK_EX))return ['status'=>'NEEDS_DATA','reason'=>'PROVIDER_LIMIT'];
 try{$counter=$dir.'/quota.json';$q=is_file($counter)?json_decode(file_get_contents($counter),true):[];if(($q['day']??'')!==gmdate('Y-m-d'))$q=['day'=>gmdate('Y-m-d'),'calls'=>0];$limit=max(1,min(1000,(int)($config['daily_limit']??20)));if($q['calls']>=$limit)return ['status'=>'NEEDS_DATA','reason'=>'PROVIDER_LIMIT'];$q['calls']++;file_put_contents($counter,json_encode($q),LOCK_EX);}finally{flock($lock,LOCK_UN);fclose($lock);}
 $body='';$ch=curl_init('https://api.openrouteservice.org/v2/directions/foot-walking/geojson');curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_HTTPHEADER=>['Authorization: '.$config['api_key'],'Content-Type: application/json'],CURLOPT_POSTFIELDS=>json_encode(['coordinates'=>$points,'instructions'=>false]),CURLOPT_CONNECTTIMEOUT=>3,CURLOPT_TIMEOUT=>8,CURLOPT_FOLLOWLOCATION=>false,CURLOPT_PROTOCOLS=>CURLPROTO_HTTPS,CURLOPT_WRITEFUNCTION=>function($curl,$chunk)use(&$body){if(strlen($body)+strlen($chunk)>1500000)return 0;$body.=$chunk;return strlen($chunk);}]);$ok=curl_exec($ch);$code=curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);
 if(!$ok||$code!==200)return ['status'=>'NEEDS_DATA','reason'=>'WALKING_PROVIDER_UNAVAILABLE'];$data=json_decode($body,true);$feature=$data['features'][0]??[];$summary=$feature['properties']['summary']??[];
 if(!is_numeric($summary['duration']??null)||!is_numeric($summary['distance']??null)||$summary['duration']<0||$summary['distance']<0||($feature['geometry']['type']??'')!=='LineString')return ['status'=>'NEEDS_DATA','reason'=>'WALKING_PROVIDER_UNAVAILABLE'];
 $result=['status'=>'NEEDS_REVIEW','provider'=>'openrouteservice','retrieved_at'=>time(),'entrance_versions'=>$versions,'value'=>['mode'=>'walk','minutes'=>(int)ceil($summary['duration']/60),'meters'=>(int)ceil($summary['distance']),'geometry'=>$feature['geometry'],'step_free'=>null],'attribution'=>'openrouteservice.org · OpenStreetMap contributors','assumptions'=>['walking estimate','entrance matching requires editorial review','step-free access not established']];
 if($ttl){$temp=tempnam($dir,'.walk-');file_put_contents($temp,json_encode($result));chmod($temp,0600);rename($temp,$cached);}return $result;
}
